let legalSkipped = 0;
const rows = [];
const META = {};
let archived = 0;
for (const k of keys) {
  if (k.is_archived) { archived++; continue; }
  const kn = k.key_name || {};
  const name = typeof kn === 'string' ? kn : (kn.web || kn.other || kn.ios || kn.android || String(k.key_id));
  let en = '';
  let tgt = '';
  for (const t of (k.translations || [])) {
    if (t.language_iso === 'en') { en = pickText(t.translation); }
    if (t.language_iso === iso) { tgt = pickText(t.translation); }
  }
  if (!en.trim() || !tgt.trim()) { continue; }
  const tags = Array.isArray(k.tags) ? k.tags.map(String) : [];
  const desc = String(k.description || k.context || '').trim();
