    if (!t.fb) { continue; }
    const bad = t.tgt || t.src;
    const f = NOSPACE ? norm(r.t).indexOf(norm(bad)) !== -1 : looseContains(r.t, bad, 0.9);
    if (f) { add({ type: 'glossary', sub: 'forbidden_used', rule: t.src, expected: '', sev: 'High', conf: 'high', key: r.k, en: r.en, target: r.t, note: t.note }); }
  }
}

// ---------- style ----------
const rules = [];
for (const r of (job.rules || [])) {
  try {
    rules.push({ r: r, f: rx(r.forbid, r.flags), w: r.when_source ? new RegExp(r.when_source, 'iu') : null });
  } catch (e) { errors.push('bad regex in rule ' + r.id + ': ' + e.message); }
}
for (const row of rows) {
